// ── FASE 26: Trial Balance ─────────────────────────────────────────────────
app.get('/api/accounting/reports/trial-balance', isAuthenticated, async (req, res) => {
  try {
    const { period, start_date, end_date } = req.query;
    let sd = start_date, ed = end_date;
    if (period && !sd) { sd = period + '-01'; const _d=new Date(period+'-01'); ed=new Date(_d.getFullYear(),_d.getMonth()+1,0).toISOString().split('T')[0]; }

    const whereClause = sd && ed ? `AND je.entry_date>='${sd}' AND je.entry_date<='${ed}'` : '';

    const { rows } = await pool.query(`
      SELECT l.account_code,
             COALESCE(a.account_name, l.account_code) as account_name,
             COALESCE(a.account_type,'unknown') as account_type,
             SUM(l.debit_amount)  as total_debits,
             SUM(l.credit_amount) as total_credits,
             SUM(l.debit_amount - l.credit_amount) as net_balance
      FROM journal_entry_lines l
      JOIN journal_entries je ON je.id=l.journal_entry_id
      LEFT JOIN chart_of_accounts a ON a.account_code=l.account_code
      WHERE je.excluded_from_reports=false AND je.status='posted' ${whereClause}
      GROUP BY l.account_code, a.account_name, a.account_type
      ORDER BY l.account_code
    `);

    const totalDebits  = rows.reduce((s,r)=>s+(parseFloat(r.total_debits)||0),0);
    const totalCredits = rows.reduce((s,r)=>s+(parseFloat(r.total_credits)||0),0);
    const difference   = Math.abs(totalDebits - totalCredits);

    res.json({
      period: { start_date: sd, end_date: ed },
      accounts: rows.map(r=>({
        account_code:  r.account_code,
        account_name:  r.account_name,
        account_type:  r.account_type,
        total_debits:  parseFloat(r.total_debits)||0,
        total_credits: parseFloat(r.total_credits)||0,
        net_balance:   parseFloat(r.net_balance)||0
      })),
      summary: {
        total_debits:  totalDebits,
        total_credits: totalCredits,
        difference,
        balanced: difference < 0.01,
        account_count: rows.length
      }
    });
  } catch (err) {
    console.error('trial-balance error:', err);
    res.status(500).json({ error: err.message });
  }
});

// ROI Analysis (by boat if boat_id provided in transactions)
app.get('/api/accounting/roi', isAuthenticated, async (req, res) => {
  try {
    const { start_date, end_date, boat_id } = req.query;
    
    if (!start_date || !end_date) {
      return res.status(400).json({ error: 'start_date and end_date are required' });
    }
    
    // Get revenue by boat (from bookings)
    let revenueQuery = `
      SELECT b.boat_type, COUNT(*) as trip_count, SUM(b.total_amount) as revenue
      FROM bookings b
      WHERE b.booking_date >= $1 AND b.booking_date <= $2
      AND b.status = 'confirmed'
    `;
    const params = [start_date, end_date];
    
    if (boat_id) {
      revenueQuery += ' AND b.boat_type = $3';
      params.push(boat_id);
    }
    
    revenueQuery += ' GROUP BY b.boat_type ORDER BY revenue DESC';
    
    const revenueResult = await pool.query(revenueQuery, params);
    
    // Get expenses (fuel, maintenance, etc.)
    const expenseResult = await pool.query(
      `SELECT a.account_name, SUM(t.amount) as total
       FROM transactions t
       JOIN chart_of_accounts a ON t.account_id = a.id
       WHERE t.transaction_date >= $1 AND t.transaction_date <= $2
       AND a.account_type = 'expense'
       GROUP BY a.account_name`,
      [start_date, end_date]
    );
    
    const total_revenue = revenueResult.rows.reduce((sum, row) => sum + parseFloat(row.revenue || 0), 0);
    const total_expenses = expenseResult.rows.reduce((sum, row) => sum + parseFloat(row.total || 0), 0);
    const net_profit = total_revenue - total_expenses;
    
    res.json({
      period: { start_date, end_date },
      by_boat: revenueResult.rows,
      expenses: expenseResult.rows,
      summary: {
        total_revenue,
        total_expenses,
        net_profit,
        roi_percentage: total_expenses > 0 ? (net_profit / total_expenses) * 100 : 0
      }
    });
  } catch (error) {
    console.error('Error generating ROI report:', error);
    res.status(500).json({ error: 'Failed to generate ROI report' });
  }
});

