// ── FASE 27: Ledger Audit & Sanitization Endpoints ───────────────────────

// GET /api/accounting/audit/ledger-integrity
app.get('/api/accounting/audit/ledger-integrity', isAuthenticated, async (req, res) => {
  try {
    // 1. Invalid account_ids (transactions not joining COA, excluding already-excluded)
    const { rows: invalidIds } = await pool.query(`
      SELECT COUNT(*) as cnt FROM transactions t
      LEFT JOIN chart_of_accounts c ON c.id = t.account_id
      WHERE c.id IS NULL AND COALESCE(t.excluded_from_ledger, false)=false
    `);

    // 2. Orphan transactions — missing account_code after backfill
    const { rows: orphanTx } = await pool.query(`
      SELECT COUNT(*) as cnt FROM transactions
      WHERE (account_code IS NULL OR account_code='')
        AND COALESCE(excluded_from_ledger, false)=false
    `);

    // 3. Duplicate entry groups (same booking+account_code+amount+date, active)
    const { rows: dupEntries } = await pool.query(`
      SELECT COUNT(*) as cnt FROM (
        SELECT booking_id, account_code, amount, transaction_date::date
        FROM transactions
        WHERE COALESCE(excluded_from_ledger, false)=false
          AND booking_id IS NOT NULL AND account_code IS NOT NULL
        GROUP BY booking_id, account_code, amount, transaction_date::date
        HAVING COUNT(*) > 1
      ) x
    `);

    // 4. Cash clearing issues per booking (1015 balance ≠ 0)
    const { rows: cashClearIssues } = await pool.query(`
      SELECT COUNT(DISTINCT t.booking_id) as cnt
      FROM transactions t
      JOIN chart_of_accounts c ON c.id = t.account_id
      WHERE c.account_code = '1015'
        AND COALESCE(t.period_type,'current')='current'
        AND COALESCE(t.excluded_from_ledger, false)=false
        AND t.booking_id IS NOT NULL
      GROUP BY t.booking_id
      HAVING ABS(SUM(CASE WHEN t.transaction_type='income' THEN t.amount ELSE -t.amount END)) > 0.01
    `);

    // 5. Unbalanced journal entries (Dr ≠ Cr)
    const { rows: unbalJE } = await pool.query(`
      SELECT COUNT(*) as cnt FROM journal_entries je
      JOIN (
        SELECT journal_entry_id,
               ABS(SUM(debit_amount) - SUM(credit_amount)) as diff
        FROM journal_entry_lines GROUP BY journal_entry_id
      ) x ON x.journal_entry_id = je.id
      WHERE x.diff > 0.01
        AND (je.excluded_from_reports=false OR je.excluded_from_reports IS NULL)
    `);

    // 6. Legacy transactions contaminating current P&L (revenue/expense accounts)
    const { rows: legacyCont } = await pool.query(`
      SELECT COUNT(*) as cnt FROM transactions t
      JOIN chart_of_accounts c ON c.id = t.account_id
      WHERE t.period_type='legacy'
        AND c.account_type IN ('revenue','expense')
        AND COALESCE(t.excluded_from_ledger, false)=false
    `);

    // 7. Transactions linked to cancelled bookings
    const { rows: cancelCont } = await pool.query(`
      SELECT COUNT(*) as cnt FROM transactions t
      JOIN bookings b ON b.id = t.booking_id
      WHERE b.status='cancelled'
        AND COALESCE(t.excluded_from_ledger, false)=false
    `);

    // 8. Matej regression: 1 captain payable record, fully paid
    const { rows: matejRows } = await pool.query(`
      SELECT COUNT(DISTINCT bcp.id) as payable_records,
             COALESCE(SUM(bcp.balance_due),0) as balance_due,
             b.total_amount
      FROM bookings b
      LEFT JOIN booking_captain_payables bcp ON bcp.booking_id=b.id
      WHERE b.id='book_matej_apr27_2026'
      GROUP BY b.total_amount
    `);
    const matejOk = matejRows.length > 0 &&
      parseInt(matejRows[0].payable_records) === 1 &&
      parseFloat(matejRows[0].balance_due) < 0.01;

    // 9. Trial balance check (posted journal entries)
    const { rows: tbRows } = await pool.query(`
      SELECT ABS(COALESCE(SUM(debit_amount),0) - COALESCE(SUM(credit_amount),0)) as diff
      FROM journal_entry_lines l
      JOIN journal_entries je ON je.id=l.journal_entry_id
      WHERE je.excluded_from_reports=false AND je.status='posted'
    `);
    const tbBalanced = parseFloat(tbRows[0]?.diff || 0) < 0.01;

    // 10. Transactions flagged for manual review
    const { rows: manualReview } = await pool.query(`
      SELECT COUNT(*) as cnt FROM transactions WHERE needs_manual_review=true
    `);

    // 11. Excluded transactions count (sanitation done)
    const { rows: excludedCount } = await pool.query(`
      SELECT COUNT(*) as cnt FROM transactions WHERE excluded_from_ledger=true
    `);

    // 12. Last sanitization log
    const { rows: lastRun } = await pool.query(`
      SELECT run_id, MAX(created_at) as run_at, COUNT(*) as issues_found
      FROM ledger_sanitization_log
      GROUP BY run_id ORDER BY MAX(created_at) DESC LIMIT 1
    `);

    const invalidIdCount    = parseInt(invalidIds[0].cnt);
    const orphanTxCount     = parseInt(orphanTx[0].cnt);
    const dupEntriesCount   = parseInt(dupEntries[0].cnt);
    const cashClearCount    = cashClearIssues.length;
    const unbalJECount      = parseInt(unbalJE[0].cnt);
    const legacyContCount   = parseInt(legacyCont[0].cnt);
    const cancelContCount   = parseInt(cancelCont[0].cnt);
    const manualReviewCount = parseInt(manualReview[0].cnt);
    const excludedTotal     = parseInt(excludedCount[0].cnt);

    const criticalIssues = [];
    const warnings = [];

    if (invalidIdCount > 0)  criticalIssues.push(`${invalidIdCount} active transactions with invalid account_id (no COA match)`);
    if (orphanTxCount > 0)   criticalIssues.push(`${orphanTxCount} active transactions missing account_code`);
    if (unbalJECount > 0)    criticalIssues.push(`${unbalJECount} unbalanced journal entries (Dr ≠ Cr)`);
    if (!matejOk)            criticalIssues.push('Matej booking regression: captain payable count or balance mismatch');
    if (!tbBalanced)         criticalIssues.push('Trial balance does not balance (posted JEs Dr ≠ Cr)');

    if (dupEntriesCount > 0)   warnings.push(`${dupEntriesCount} duplicate entry groups in active ledger`);
    if (cashClearCount > 0)    warnings.push(`${cashClearCount} bookings with unresolved cash clearing balance (1015)`);
    if (legacyContCount > 0)   warnings.push(`${legacyContCount} legacy transactions on active revenue/expense accounts`);
    if (cancelContCount > 0)   warnings.push(`${cancelContCount} transactions linked to cancelled bookings`);
    if (manualReviewCount > 0) warnings.push(`${manualReviewCount} transactions flagged for manual review (null booking_id on revenue)`);

    const overallStatus = criticalIssues.length > 0 ? 'fail' :
                          warnings.length > 0 ? 'warning' : 'pass';

    res.json({
      status: overallStatus,
      timestamp: new Date().toISOString(),
      invalid_account_ids: invalidIdCount,
      orphan_transactions: orphanTxCount,
      duplicate_entries: dupEntriesCount,
      cash_clearing_issues: cashClearCount,
      unbalanced_journal_entries: unbalJECount,
      legacy_contamination: legacyContCount,
      cancelled_contamination: cancelContCount,
      needs_manual_review: manualReviewCount,
      excluded_from_ledger_total: excludedTotal,
      matej_regression: matejOk ? 'pass' : 'fail',
      trial_balance: tbBalanced ? 'pass' : 'fail',
      balance_sheet: 'see /api/accounting/reports/balance-sheet',
      critical_issues: criticalIssues,
      warnings,
      last_run_id: lastRun.length > 0 ? lastRun[0].run_id : null,
      last_run_at: lastRun.length > 0 ? lastRun[0].run_at : null,
      last_run_issues_logged: lastRun.length > 0 ? parseInt(lastRun[0].issues_found) : 0
    });
  } catch (err) {
    console.error('Ledger integrity check error:', err);
    res.status(500).json({ error: 'Failed to run ledger integrity check', details: err.message });
  }
});

// POST /api/accounting/audit/ledger-sanitize
app.post('/api/accounting/audit/ledger-sanitize', isAuthenticated, async (req, res) => {
  const { dry_run = true, scope = 'all', created_by = 'admin' } = req.body;
  const runId = 'sanitize_' + Date.now();
  const actions = [];

  const pg = await pool.connect();
  try {
    if (!dry_run) await pg.query('BEGIN');

    // STEP 1: Backfill account_code for transactions that are missing it
    if (scope === 'all' || scope === 'account_ids') {
      const { rows: needsFill } = await pg.query(`
        SELECT t.id, c.account_code, c.account_name
        FROM transactions t
        JOIN chart_of_accounts c ON c.id=t.account_id
        WHERE t.account_code IS NULL OR t.account_code=''
      `);
      for (const tx of needsFill) {
        actions.push({ action: 'BACKFILL_ACCOUNT_CODE', table: 'transactions', record_id: tx.id, account_code: tx.account_code, dry_run });
        if (!dry_run) {
          await pg.query(`UPDATE transactions SET account_code=$1 WHERE id=$2`, [tx.account_code, tx.id]);
          await pg.query(`
            INSERT INTO ledger_sanitization_log (run_id,issue_type,severity,table_name,record_id,action_taken,reason,created_by)
            VALUES ($1,'MISSING_ACCOUNT_CODE','low','transactions',$2,'SET account_code from COA join','Backfill missing account_code',$3)
          `, [runId, tx.id, created_by]);
        }
      }
    }

    // STEP 2: Fix known wrong account mappings
    if (scope === 'all' || scope === 'account_ids') {
      const wrongMappings = [
        { id: 'tx_matej_3a', correct_code: '5020', correct_id: 'YOYzbQUHSTFh9ykXRwDoi',
          reason: 'Description says Fuel Expense but account_code was 5010 Captain Labor — corrected to 5020' }
      ];
      for (const fix of wrongMappings) {
        const { rows: txData } = await pg.query(`SELECT id, account_code, account_id FROM transactions WHERE id=$1`, [fix.id]);
        if (txData.length > 0 && txData[0].account_code !== fix.correct_code) {
          actions.push({ action: 'FIX_WRONG_ACCOUNT', table: 'transactions', record_id: fix.id,
            from_code: txData[0].account_code, to_code: fix.correct_code, reason: fix.reason, dry_run });
          if (!dry_run) {
            await pg.query(`UPDATE transactions SET account_code=$1, account_id=$2 WHERE id=$3`,
              [fix.correct_code, fix.correct_id, fix.id]);
            await pg.query(`
              INSERT INTO ledger_sanitization_log (run_id,issue_type,severity,table_name,record_id,booking_id,before_state_json,after_state_json,action_taken,reason,created_by)
              VALUES ($1,'WRONG_ACCOUNT_CODE','medium','transactions',$2,'book_matej_apr27_2026',$3,$4,'UPDATE account_code',$5,$6)
            `, [runId, fix.id, JSON.stringify(txData[0]),
               JSON.stringify({...txData[0], account_code: fix.correct_code, account_id: fix.correct_id}),
               fix.reason, created_by]);
          }
        }
      }
    }

    // STEP 3: Mark duplicate wizard transactions as excluded_from_ledger
    if (scope === 'all' || scope === 'duplicates' || scope === 'matej') {
      const DUPE_IDS = [
        'tx_cpay_cr_tlIn87UF','tx_cpay_dr_itpW8QTM',
        'tx_cpmt_cr_CbQJVauo','tx_cpmt_dr_D58nWrkU',
        'tx_cpmt_cr_rpHdqx_z','tx_cpmt_dr_iMMb0-Ks'
      ];
      for (const txId of DUPE_IDS) {
        const { rows: txData } = await pg.query(
          `SELECT id, excluded_from_ledger, account_code, amount, description FROM transactions WHERE id=$1`, [txId]);
        if (txData.length > 0 && !txData[0].excluded_from_ledger) {
          actions.push({ action: 'EXCLUDE_DUPLICATE', table: 'transactions', record_id: txId,
            amount: parseFloat(txData[0].amount), account_code: txData[0].account_code,
            reason: 'Booking wizard ran twice for book_matej_apr27_2026 — second set excluded', dry_run });
          if (!dry_run) {
            await pg.query(`
              UPDATE transactions SET excluded_from_ledger=true,
                exclusion_reason='FASE27 duplicate sanitation — booking_wizard ran twice for book_matej_apr27_2026',
                excluded_at=NOW(), excluded_by=$1
              WHERE id=$2
            `, [created_by, txId]);
            await pg.query(`
              INSERT INTO ledger_sanitization_log (run_id,issue_type,severity,table_name,record_id,booking_id,before_state_json,after_state_json,action_taken,reason,created_by)
              VALUES ($1,'DUPLICATE_WIZARD_TRANSACTION','high','transactions',$2,'book_matej_apr27_2026',$3,$4,'SET excluded_from_ledger=true','Booking wizard ran twice for Matej',$5)
            `, [runId, txId, JSON.stringify(txData[0]),
               JSON.stringify({...txData[0], excluded_from_ledger: true}), created_by]);
          }
        }
      }
    }

    // STEP 4: Flag null-booking revenue transactions for manual review
    if (scope === 'all') {
      const { rows: nullRev } = await pg.query(`
        SELECT id, amount, description FROM transactions
        WHERE booking_id IS NULL AND transaction_type='income'
          AND account_code IN ('4010','4020')
          AND COALESCE(needs_manual_review, false)=false
      `);
      for (const tx of nullRev) {
        actions.push({ action: 'FLAG_MANUAL_REVIEW', table: 'transactions', record_id: tx.id,
          amount: parseFloat(tx.amount), reason: 'Revenue transaction with NULL booking_id', dry_run });
        if (!dry_run) {
          await pg.query(`UPDATE transactions SET needs_manual_review=true WHERE id=$1`, [tx.id]);
          await pg.query(`
            INSERT INTO ledger_sanitization_log (run_id,issue_type,severity,table_name,record_id,action_taken,reason,created_by)
            VALUES ($1,'NULL_BOOKING_REVENUE','low','transactions',$2,'SET needs_manual_review=true','Revenue with no booking_id',$3)
          `, [runId, tx.id, created_by]);
        }
      }
    }

    if (!dry_run) {
      await pg.query('COMMIT');
      const { rows: totalRows } = await pg.query(`SELECT COUNT(*) as cnt FROM transactions`);
      await pg.query(`
        INSERT INTO ledger_sanitization_snapshots (run_id, snapshot_table, total_rows)
        VALUES ($1, 'transactions', $2)
      `, [runId, parseInt(totalRows[0].cnt)]);
    }

    const byAction = {};
    actions.forEach(a => { byAction[a.action] = (byAction[a.action]||0)+1; });

    res.json({
      dry_run,
      run_id: dry_run ? 'DRY_RUN_' + runId : runId,
      scope,
      created_by,
      actions_count: actions.length,
      actions_by_type: byAction,
      actions,
      status: dry_run ? 'dry_run_complete' : 'sanitization_applied',
      message: dry_run
        ? `Dry run complete — ${actions.length} action(s) would be applied. Call with dry_run=false to apply.`
        : `Sanitization applied — ${actions.length} change(s) logged to ledger_sanitization_log.`
    });
  } catch (err) {
    if (!dry_run) await pg.query('ROLLBACK').catch(()=>{});
    console.error('Ledger sanitize error:', err);
    res.status(500).json({ error: 'Sanitization failed', details: err.message });
  } finally { pg.release(); }
});

// GET /api/accounting/audit/sanitization-log — review what was changed
app.get('/api/accounting/audit/sanitization-log', isAuthenticated, async (req, res) => {
  try {
    const { run_id, limit = 50, severity } = req.query;
    let where = 'WHERE 1=1';
    const params = [];
    if (run_id)   { params.push(run_id);   where += ` AND run_id=$${params.length}`; }
    if (severity) { params.push(severity); where += ` AND severity=$${params.length}`; }
    const { rows: logs } = await pool.query(`
      SELECT * FROM ledger_sanitization_log ${where}
      ORDER BY created_at DESC LIMIT $${params.length+1}
    `, [...params, parseInt(limit)]);
    const { rows: runs } = await pool.query(`
      SELECT run_id, COUNT(*) as total, MAX(created_at) as run_at,
             COUNT(CASE WHEN severity='high' THEN 1 END) as high_count,
             COUNT(CASE WHEN severity='medium' THEN 1 END) as medium_count,
             COUNT(CASE WHEN severity='low' THEN 1 END) as low_count
      FROM ledger_sanitization_log GROUP BY run_id ORDER BY MAX(created_at) DESC LIMIT 10
    `);
    res.json({ runs, logs, total: logs.length });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// GET /api/bookings/:id/reconciliation — full booking ledger reconciliation
// ── FASE 28 FIX: Reconciliation endpoint — enriched with full wizard data ─
// Previously the FASE 27 endpoint returned a stripped GL-audit structure
// (revenue.items, direct_costs.items, summary.*) that the wizard cannot use.
// This replacement calls checkBookingIntegrity() which returns ALL wizard fields
// (expected_revenue, total_collected, total_expenses, expected_profit,
//  cash_clearing_balance, accounting_status, booking_date, platform, status,
//  total_ar_pending, alerts[], suggested_next_action) and ALSO includes
//  the FASE 27 GL-audit data and the wizard's deposits/transactions arrays.
app.get('/api/bookings/:id/reconciliation', isAuthenticated, async (req, res) => {
  try {
    const bookingId = req.params.id;

    // 1. Full integrity data — provides ALL fields the wizard needs
    const integrity = await checkBookingIntegrity(bookingId);
    if (!integrity) return res.status(404).json({ error: 'Booking no encontrado' });

    // 2. Parallel fetch: transactions, deposits, expenses, excluded GL items
    const [txRes, depRes, expRes, revRes, expGLRes, exclRes] = await Promise.all([
      // All ACTIVE (non-voided) transactions linked to this booking (for wizard payment list)
      pool.query(
        `SELECT t.id, t.transaction_date, t.amount, t.transaction_type, t.description,
                t.reference_type, t.notes, t.account_id,
                c.account_code, c.account_name
         FROM transactions t
         LEFT JOIN chart_of_accounts c ON c.id = t.account_id
         WHERE t.booking_id = $1
           AND COALESCE(t.excluded_from_ledger, false) = false
         ORDER BY t.transaction_date DESC, t.id DESC LIMIT 150`,
        [bookingId]
      ).catch(() => ({ rows: [] })),
      // Deposits (via bookings_ledger join)
      pool.query(
        `SELECT bd.* FROM booking_deposits bd
         JOIN bookings_ledger bl ON bl.id = bd.booking_ledger_id
         WHERE bl.notes LIKE 'booking:' || $1 || '%'
         ORDER BY bd.deposit_date DESC`,
        [bookingId]
      ).catch(() => ({ rows: [] })),
      // Boat expenses (for wizard expense list) — exclude voided/cancelled
      pool.query(
        `SELECT * FROM boat_expenses
         WHERE booking_id = $1
           AND COALESCE(status, 'active') NOT IN ('voided','cancelled')
         ORDER BY expense_date ASC`,
        [bookingId]
      ).catch(() => ({ rows: [] })),
      // Revenue GL rows (4xxx income transactions, FASE 27 style)
      pool.query(`
        SELECT COALESCE(t.account_code,c.account_code) as account_code, c.account_name,
               SUM(CASE WHEN t.amount < 0 THEN -t.amount ELSE t.amount END) as total
        FROM transactions t JOIN chart_of_accounts c ON c.id=t.account_id
        WHERE t.booking_id=$1 AND t.transaction_type='income'
          AND COALESCE(t.account_code, c.account_code)::text LIKE '4%'
          AND COALESCE(t.excluded_from_ledger, false)=false
        GROUP BY COALESCE(t.account_code,c.account_code), c.account_name
      `, [bookingId]).catch(() => ({ rows: [] })),
      // Expense GL rows (5xxx expense transactions, FASE 27 style)
      pool.query(`
        SELECT COALESCE(t.account_code,c.account_code) as account_code, c.account_name,
               SUM(t.amount) as total
        FROM transactions t JOIN chart_of_accounts c ON c.id=t.account_id
        WHERE t.booking_id=$1 AND t.transaction_type='expense'
          AND COALESCE(t.account_code, c.account_code)::text LIKE '5%'
          AND COALESCE(t.excluded_from_ledger, false)=false
        GROUP BY COALESCE(t.account_code,c.account_code), c.account_name
        ORDER BY COALESCE(t.account_code,c.account_code)
      `, [bookingId]).catch(() => ({ rows: [] })),
      // Excluded transactions (FASE 27 audit trail)
      pool.query(`
        SELECT t.id, COALESCE(t.account_code,c.account_code) as account_code,
               t.amount, t.description, t.exclusion_reason, t.excluded_at
        FROM transactions t JOIN chart_of_accounts c ON c.id=t.account_id
        WHERE t.booking_id=$1 AND t.excluded_from_ledger=true
        ORDER BY t.excluded_at
      `, [bookingId]).catch(() => ({ rows: [] })),
    ]);

    const revRows  = revRes.rows;
    const expGLRows = expGLRes.rows;
    const exclRows = exclRes.rows;
    const total_revenue      = revRows.reduce((s,r)=>s+parseFloat(r.total||0),0);
    const total_direct_costs = expGLRows.reduce((s,r)=>s+parseFloat(r.total||0),0);
    const profit             = total_revenue - total_direct_costs;

    // 3. Merge: integrity fields (wizard-required) + GL-audit data (FASE 27) + collections
    res.json({
      // ── Core booking identification ─────────────────────────────────────────
      booking_id:     bookingId,
      customer_name:  integrity.customer_name,
      booking_date:   integrity.booking_date,
      platform:       integrity.platform,
      status:         integrity.status,

      // ── Booking total — normalized across all callers ───────────────────────
      booking_total:   integrity.expected_revenue,   // primary canonical field
      total_amount:    integrity.expected_revenue,   // alias
      display_total:   integrity.expected_revenue,   // alias for display

      // ── Wizard Step 1 fields (checkBookingIntegrity) ────────────────────────
      expected_revenue:         integrity.expected_revenue,
      total_collected:          integrity.total_collected,
      total_deposits:           integrity.total_deposits,
      total_cash:               integrity.total_cash,
      total_ar_paid:            integrity.total_ar_paid,
      total_ar_pending:         integrity.total_ar_pending,
      total_expenses:           integrity.total_expenses,
      expected_profit:          integrity.expected_profit,
      actual_profit:            integrity.actual_profit,
      revenue_recognized_amount: integrity.revenue_recognized_amount,
      revenue_recognized:       integrity.revenue_recognized,
      discrepancy_flag:         integrity.discrepancy_flag,
      discrepancy_amount:       integrity.discrepancy_amount,
      accounting_status:        integrity.accounting_status,
      cash_clearing_balance:    integrity.cash_clearing_balance,
      cash_clearing_in:         integrity.cash_clearing_in,
      cash_clearing_out:        integrity.cash_clearing_out,

      // ── Captain & payables (wizard steps 3–4) ─────────────────────────────
      captain_actual:            integrity.captain_actual,
      captain_hours:             integrity.captain_hours,
      captain_payable_due:       integrity.captain_payable_due,
      captain_payable_paid:      integrity.captain_payable_paid,
      captain_payable_balance:   integrity.captain_payable_balance,
      captain_payable_status:    integrity.captain_payable_status,
      general_payables_due:      integrity.general_payables_due,
      general_payables_paid:     integrity.general_payables_paid,
      general_payables_balance:  integrity.general_payables_balance,
      general_payables_status:   integrity.general_payables_status,
      total_payables_balance:    integrity.total_payables_balance,
      can_close_with_open_payables: integrity.can_close_with_open_payables,
      is_legacy:                 integrity.is_legacy,

      // ── Alerts & next action ───────────────────────────────────────────────
      alerts:               integrity.alerts,
      suggested_next_action: integrity.suggested_next_action,

      // ── Collection arrays (wizard steps 2 & 4) ────────────────────────────
      transactions: txRes.rows,
      deposits:     depRes.rows,
      expenses:     expRes.rows,

      // ── FASE 27 GL-audit data (for audit table + ledger panel) ─────────────
      revenue: { items: revRows, total: total_revenue },
      direct_costs: { items: expGLRows, total: total_direct_costs },
      summary: {
        total_revenue,
        total_direct_costs,
        profit,
        profit_margin: total_revenue > 0 ? ((profit/total_revenue)*100).toFixed(1)+'%' : 'n/a',
        cash_clearing_balanced: Math.abs(integrity.cash_clearing_balance) <= 0.01
      },
      excluded_transactions: { count: exclRows.length, items: exclRows },
      ledger_id: integrity.ledger_id,
    });
  } catch (err) {
    console.error('Reconciliation error:', err);
    res.status(500).json({ error: 'Failed to generate reconciliation', details: err.message });
  }
});

// ── END FASE 27 / FASE 28 Audit Endpoints ────────────────────────────────

// ── FASE 29: GET /api/accounting/audit/reversal-state ─────────────────────
// Audit endpoint: per-booking snapshot of active vs voided items + inconsistencies.
app.get('/api/accounting/audit/reversal-state', isAuthenticated, async (req, res) => {
  const bookingId = req.query.booking_id;
  if (!bookingId) return res.status(400).json({ error: 'booking_id query param required' });
  try {
    const [txActive, txVoided, expActive, expVoided, cpActive, cpVoided] = await Promise.all([
      // Active income transactions (client payments)
      pool.query(`
        SELECT t.id, t.amount, t.account_code, t.transaction_date, t.description
        FROM transactions t
        WHERE t.booking_id=$1 AND t.transaction_type='income'
          AND COALESCE(t.excluded_from_ledger,false)=false
        ORDER BY t.transaction_date DESC`, [bookingId]),
      // Voided income transactions
      pool.query(`
        SELECT t.id, t.amount, t.account_code, t.transaction_date, t.voided_reason
        FROM transactions t
        WHERE t.booking_id=$1 AND t.transaction_type='income'
          AND COALESCE(t.excluded_from_ledger,false)=true
        ORDER BY t.transaction_date DESC`, [bookingId]),
      // Active expenses
      pool.query(`
        SELECT id, amount, category, payment_method, expense_date, description
        FROM boat_expenses
        WHERE booking_id=$1 AND COALESCE(status,'active') NOT IN ('voided','cancelled')
        ORDER BY expense_date ASC`, [bookingId]),
      // Voided expenses
      pool.query(`
        SELECT id, amount, category, payment_method, expense_date, status, voided_reason
        FROM boat_expenses
        WHERE booking_id=$1 AND status IN ('voided','cancelled')
        ORDER BY expense_date ASC`, [bookingId]),
      // Active captain payments
      pool.query(`
        SELECT bcp.id, bcp.amount, bcp.payment_method, bcp.payment_date, bcp2.captain_name
        FROM booking_captain_payments bcp
        JOIN booking_captain_payables bcp2 ON bcp2.id=bcp.captain_payable_id
        WHERE bcp.booking_id=$1 AND COALESCE(bcp.voided,false)=false
        ORDER BY bcp.payment_date DESC`, [bookingId]).catch(()=>({rows:[]})),
      // Voided captain payments
      pool.query(`
        SELECT bcp.id, bcp.amount, bcp.payment_method, bcp.payment_date, bcp.voided_reason, bcp2.captain_name
        FROM booking_captain_payments bcp
        JOIN booking_captain_payables bcp2 ON bcp2.id=bcp.captain_payable_id
        WHERE bcp.booking_id=$1 AND COALESCE(bcp.voided,false)=true
        ORDER BY bcp.payment_date DESC`, [bookingId]).catch(()=>({rows:[]})),
    ]);

    const ledgerActiveAmt  = txActive.rows.reduce((s,t)=>s+parseFloat(t.amount||0),0);
    const reversedAmt      = txVoided.rows.reduce((s,t)=>s+parseFloat(t.amount||0),0);
    const cashClearingAmt  = txActive.rows.filter(t=>t.account_code==='1015').reduce((s,t)=>s+parseFloat(t.amount||0),0);

    // Detect inconsistencies
    const inconsistencies = [];

    // Source voided but linked tx still active
    for (const exp of expVoided.rows) {
      const { rows: activeTx } = await pool.query(
        `SELECT id FROM transactions WHERE reference_id=$1 AND COALESCE(excluded_from_ledger,false)=false LIMIT 1`, [exp.id]
      ).catch(()=>({rows:[]}));
      if (activeTx.length) {
        inconsistencies.push({
          type: 'expense_voided_but_tx_active',
          source_id: exp.id, source_type: 'boat_expense', amount: exp.amount,
          message: `Expense ${exp.id} is voided but linked transaction is still active in ledger`,
          fix: `POST /api/accounting/reverse {source_type:"booking_expense",source_id:"${exp.id}"}`
        });
      }
    }

    // Source active but reversal log exists (partially voided)
    for (const tx of txActive.rows) {
      const { rows: rvl } = await pool.query(
        `SELECT id FROM accounting_reversal_log WHERE source_id=$1 LIMIT 1`, [tx.id]
      ).catch(()=>({rows:[]}));
      if (rvl.length) {
        inconsistencies.push({
          type: 'tx_active_but_reversal_log_exists',
          source_id: tx.id, source_type: 'transaction', amount: tx.amount,
          message: `Transaction ${tx.id} is still active but a reversal log entry exists`,
        });
      }
    }

    res.json({
      booking_id:              bookingId,
      active_payments:         txActive.rows,
      voided_payments:         txVoided.rows,
      active_expenses:         expActive.rows,
      voided_expenses:         expVoided.rows,
      active_captain_payments: cpActive.rows,
      voided_captain_payments: cpVoided.rows,
      ledger_active_amount:    ledgerActiveAmt,
      reversed_amount:         reversedAmt,
      cash_clearing_active:    cashClearingAmt,
      inconsistencies,
      summary: {
        active_payment_count:  txActive.rows.length,
        voided_payment_count:  txVoided.rows.length,
        active_expense_count:  expActive.rows.length,
        voided_expense_count:  expVoided.rows.length,
        captain_paid_active:   cpActive.rows.reduce((s,p)=>s+parseFloat(p.amount||0),0),
        captain_paid_voided:   cpVoided.rows.reduce((s,p)=>s+parseFloat(p.amount||0),0),
        inconsistency_count:   inconsistencies.length,
      }
    });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ── FASE 28: Regression Engine — GET /api/accounting/audit/regression-status
// Runs a comprehensive regression audit across all accounting modules and returns
// a structured report of issues, warnings, and pass/fail status per module.
app.get('/api/accounting/audit/regression-status', isAuthenticated, async (req, res) => {
  const runId = `audit_run_fase28_${new Date().toISOString().slice(0,10).replace(/-/g,'')}`;
  const issues = [];
  const warnings = [];
  const moduleResults = [];

  const check = async (label, fn) => {
    try {
      const r = await fn();
      moduleResults.push({ module: label, status: r.status, details: r.details || null, count: r.count ?? null });
      if (r.status === 'FAIL') issues.push({ module: label, message: r.message || label, items: r.items || [] });
      if (r.status === 'WARN') warnings.push({ module: label, message: r.message || label, items: r.items || [] });
    } catch (e) {
      moduleResults.push({ module: label, status: 'ERROR', details: e.message });
      issues.push({ module: label, message: `Exception: ${e.message}`, items: [] });
    }
  };

  // ── 1. Booking total normalization ─────────────────────────────────────────
  await check('booking_total_normalization', async () => {
    const { rows } = await pool.query(
      `SELECT id, customer_name, total_amount FROM bookings WHERE total_amount IS NULL OR total_amount <= 0`
    );
    return rows.length === 0
      ? { status: 'PASS', count: 0, details: 'All bookings have total_amount > 0' }
      : { status: 'FAIL', count: rows.length,
          message: `${rows.length} bookings with total_amount = NULL or 0`,
          items: rows.map(r => ({ id: r.id, customer: r.customer_name, total: r.total_amount })) };
  });

  // ── 2. Duplicate captain payables ──────────────────────────────────────────
  await check('duplicate_captain_payables', async () => {
    const { rows } = await pool.query(
      `SELECT booking_id, COUNT(*) as cnt FROM booking_captain_payables
       GROUP BY booking_id HAVING COUNT(*) > 1`
    );
    return rows.length === 0
      ? { status: 'PASS', count: 0, details: 'No duplicate captain payable records' }
      : { status: 'FAIL', count: rows.length,
          message: `${rows.length} bookings with duplicate captain payables`,
          items: rows.map(r => ({ booking_id: r.booking_id, count: r.cnt })) };
  });

  // ── 3. Orphan transactions (booking_id not in bookings) ────────────────────
  await check('orphan_transactions', async () => {
    const { rows } = await pool.query(
      `SELECT t.id, t.booking_id, t.amount, t.description FROM transactions t
       WHERE t.booking_id IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM bookings b WHERE b.id = t.booking_id)
       LIMIT 20`
    );
    return rows.length === 0
      ? { status: 'PASS', count: 0, details: 'No orphan transactions' }
      : { status: 'WARN', count: rows.length,
          message: `${rows.length} transactions reference non-existent bookings`,
          items: rows.map(r => ({ id: r.id, booking_id: r.booking_id, amount: r.amount })) };
  });

  // ── 4. Transactions without account mapping ────────────────────────────────
  await check('unmapped_transactions', async () => {
    const { rows } = await pool.query(
      `SELECT COUNT(*) as cnt FROM transactions t
       WHERE t.account_id IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM chart_of_accounts c WHERE c.id = t.account_id)`
    );
    const cnt = parseInt(rows[0].cnt);
    return cnt === 0
      ? { status: 'PASS', count: 0, details: 'All transactions have valid account mapping' }
      : { status: 'FAIL', count: cnt, message: `${cnt} transactions with invalid account_id` };
  });

  // ── 5. AR receivables with no linked booking ───────────────────────────────
  // Note: some AR records use bookings_ledger IDs (bl_*) in booking_id column — those are valid
  await check('orphan_ar_receivables', async () => {
    const { rows } = await pool.query(
      `SELECT COUNT(*) as cnt FROM booking_receivables br
       WHERE br.booking_id IS NOT NULL
         AND br.booking_id NOT LIKE 'bl_%'
         AND NOT EXISTS (SELECT 1 FROM bookings b WHERE b.id = br.booking_id)`
    ).catch(() => ({ rows: [{ cnt: 0 }] }));
    const cnt = parseInt(rows[0].cnt);
    return cnt === 0
      ? { status: 'PASS', count: 0, details: 'All AR receivables linked to valid bookings or ledger records' }
      : { status: 'WARN', count: cnt, message: `${cnt} AR records reference missing bookings (not via ledger)` };
  });

  // ── 6. Open cash clearing anomalies (excludes QA test bookings) ──────────
  await check('open_cash_clearing', async () => {
    const { rows } = await pool.query(
      `SELECT t.booking_id,
              SUM(CASE WHEN t.transaction_type='income' THEN t.amount ELSE -t.amount END) as bal
       FROM transactions t
       JOIN chart_of_accounts c ON c.id = t.account_id
       WHERE COALESCE(t.account_code, c.account_code) = '1015'
         AND t.booking_id IS NOT NULL
         AND t.booking_id NOT LIKE 'book_QA_%'
         AND COALESCE(t.excluded_from_ledger, false) = false
       GROUP BY t.booking_id
       HAVING ABS(SUM(CASE WHEN t.transaction_type='income' THEN t.amount ELSE -t.amount END)) > 0.01
       ORDER BY ABS(SUM(CASE WHEN t.transaction_type='income' THEN t.amount ELSE -t.amount END)) DESC
       LIMIT 20`
    ).catch(() => ({ rows: [] }));
    return rows.length === 0
      ? { status: 'PASS', count: 0, details: 'All Cash Clearing (1015) balances are zero (QA bookings excluded)' }
      : { status: 'WARN', count: rows.length,
          message: `${rows.length} production bookings with open Cash Clearing (1015) balance`,
          items: rows.map(r => ({ booking_id: r.booking_id, balance: parseFloat(r.bal).toFixed(2) })) };
  });

  // ── 7. Duplicate transactions (same booking, amount, date, type) ───────────
  // Excludes QA test bookings (book_QA_*) which intentionally have repeated transactions
  await check('duplicate_transactions', async () => {
    const { rows } = await pool.query(
      `SELECT booking_id, transaction_date, amount, transaction_type, COUNT(*) as cnt
       FROM transactions
       WHERE booking_id IS NOT NULL
         AND booking_id NOT LIKE 'book_QA_%'
         AND COALESCE(excluded_from_ledger, false) = false
       GROUP BY booking_id, transaction_date, amount, transaction_type
       HAVING COUNT(*) > 2
       ORDER BY cnt DESC LIMIT 10`
    ).catch(() => ({ rows: [] }));
    return rows.length === 0
      ? { status: 'PASS', count: 0, details: 'No suspicious duplicate transaction groups (QA bookings excluded)' }
      : { status: 'WARN', count: rows.length,
          message: `${rows.length} groups with possible duplicate transactions`,
          items: rows.map(r => ({ booking_id: r.booking_id, date: r.transaction_date, amount: r.amount, type: r.transaction_type, count: r.cnt })) };
  });

  // ── 8. Bookings missing ledger entry ──────────────────────────────────────
  await check('bookings_missing_ledger', async () => {
    const { rows } = await pool.query(
      `SELECT b.id, b.customer_name, b.total_amount, b.status FROM bookings b
       WHERE b.status NOT IN ('cancelled','draft')
         AND NOT EXISTS (
           SELECT 1 FROM bookings_ledger bl WHERE bl.notes LIKE 'booking:' || b.id || '%'
         )
       LIMIT 20`
    ).catch(() => ({ rows: [] }));
    return rows.length === 0
      ? { status: 'PASS', count: 0, details: 'All active bookings have a ledger entry' }
      : { status: 'WARN', count: rows.length,
          message: `${rows.length} active bookings with no bookings_ledger record`,
          items: rows.map(r => ({ id: r.id, customer: r.customer_name, total: r.total_amount })) };
  });

  // ── 9. Ledger sanitization log (FASE 27) ──────────────────────────────────
  await check('ledger_sanitization_log', async () => {
    const { rows } = await pool.query(
      `SELECT action_taken, COUNT(*) as cnt FROM ledger_sanitization_log GROUP BY action_taken ORDER BY cnt DESC LIMIT 10`
    ).catch(() => ({ rows: [] }));
    return { status: 'PASS', count: rows.reduce((s,r)=>s+parseInt(r.cnt),0),
      details: rows.map(r=>`${r.action_taken}: ${r.cnt}`).join(', ') || 'No sanitization log entries' };
  });

  // ── 10. Wizard field test — sample booking ────────────────────────────────
  await check('wizard_reconciliation_fields', async () => {
    const { rows: bkRows } = await pool.query(
      `SELECT id FROM bookings WHERE total_amount > 0 ORDER BY booking_date DESC LIMIT 1`
    );
    if (!bkRows.length) return { status: 'PASS', details: 'No bookings to test' };
    const integrity = await checkBookingIntegrity(bkRows[0].id).catch(() => null);
    if (!integrity) return { status: 'FAIL', message: 'checkBookingIntegrity returned null for most recent booking' };
    const required = ['expected_revenue','total_collected','total_expenses','expected_profit',
                      'cash_clearing_balance','accounting_status','booking_date','platform',
                      'status','total_ar_pending','alerts','suggested_next_action'];
    const missing = required.filter(f => integrity[f] === undefined);
    return missing.length === 0
      ? { status: 'PASS', count: 0,
          details: `All ${required.length} wizard fields present. expected_revenue=$${integrity.expected_revenue?.toFixed(2)}, accounting_status=${integrity.accounting_status}` }
      : { status: 'FAIL', count: missing.length, message: `Missing wizard fields: ${missing.join(', ')}` };
  });

  // ── 11. Captain payable balance integrity ─────────────────────────────────
  await check('captain_payable_balance_integrity', async () => {
    const { rows } = await pool.query(
      `SELECT bcp.booking_id, b.customer_name, bcp.balance_due, bcp.status
       FROM booking_captain_payables bcp
       JOIN bookings b ON b.id = bcp.booking_id
       WHERE ABS(bcp.balance_due) > 0.01
         AND bcp.status IN ('paid','settled','cleared')
       LIMIT 10`
    ).catch(() => ({ rows: [] }));
    return rows.length === 0
      ? { status: 'PASS', count: 0, details: 'All paid captain payables have zero balance_due' }
      : { status: 'WARN', count: rows.length,
          message: `${rows.length} captain payable records marked paid but balance_due != 0`,
          items: rows.map(r => ({ booking_id: r.booking_id, customer: r.customer_name, balance: r.balance_due, status: r.status })) };
  });

  // ── 12. Revenue account sanity (4xxx) ─────────────────────────────────────
  await check('revenue_account_sanity', async () => {
    const { rows } = await pool.query(
      `SELECT t.id, t.booking_id, t.amount, c.account_code
       FROM transactions t
       JOIN chart_of_accounts c ON c.id = t.account_id
       WHERE t.transaction_type = 'income'
         AND COALESCE(t.excluded_from_ledger, false) = false
         AND c.account_code::text NOT LIKE '1%'
         AND c.account_code::text NOT LIKE '4%'
         AND c.account_code::text NOT LIKE '2%'
       LIMIT 10`
    ).catch(() => ({ rows: [] }));
    return rows.length === 0
      ? { status: 'PASS', count: 0, details: 'Income transactions routed to valid asset/revenue/liability accounts' }
      : { status: 'WARN', count: rows.length,
          message: `${rows.length} income transactions on unexpected account types`,
          items: rows.map(r => ({ id: r.id, booking_id: r.booking_id, amount: r.amount, account_code: r.account_code })) };
  });

  // ── 13. Expense account sanity (5xxx) ─────────────────────────────────────
  await check('expense_account_sanity', async () => {
    const { rows } = await pool.query(
      `SELECT t.id, t.booking_id, t.amount, c.account_code
       FROM transactions t
       JOIN chart_of_accounts c ON c.id = t.account_id
       WHERE t.transaction_type = 'expense'
         AND COALESCE(t.excluded_from_ledger, false) = false
         AND c.account_code::text NOT LIKE '5%'
         AND c.account_code::text NOT LIKE '1%'
         AND c.account_code::text NOT LIKE '2%'
         AND c.account_code::text NOT LIKE '6%'
       LIMIT 10`
    ).catch(() => ({ rows: [] }));
    return rows.length === 0
      ? { status: 'PASS', count: 0, details: 'Expense transactions routed to valid expense/asset/liability accounts' }
      : { status: 'WARN', count: rows.length,
          message: `${rows.length} expense transactions on unexpected account types`,
          items: rows.map(r => ({ id: r.id, booking_id: r.booking_id, amount: r.amount, account_code: r.account_code })) };
  });

  // ── 14. Expense overrun anomalies ─────────────────────────────────────────
  // Flag bookings where total non-excluded expenses exceed 2× total revenue
  await check('expense_overrun_anomalies', async () => {
    const { rows } = await pool.query(
      `SELECT t.booking_id,
              SUM(CASE WHEN t.transaction_type='income' AND t.amount > 0 THEN t.amount ELSE 0 END) as revenue,
              SUM(CASE WHEN t.transaction_type='expense' AND t.amount > 0 THEN t.amount ELSE 0 END) as expenses
       FROM transactions t
       WHERE t.booking_id IS NOT NULL
         AND COALESCE(t.excluded_from_ledger, false) = false
         AND t.booking_id NOT LIKE 'book_QA_%'
       GROUP BY t.booking_id
       HAVING SUM(CASE WHEN t.transaction_type='expense' AND t.amount > 0 THEN t.amount ELSE 0 END)
              > 2 * NULLIF(SUM(CASE WHEN t.transaction_type='income' AND t.amount > 0 THEN t.amount ELSE 0 END), 0)
         AND SUM(CASE WHEN t.transaction_type='income' AND t.amount > 0 THEN t.amount ELSE 0 END) > 0
       LIMIT 10`
    ).catch(() => ({ rows: [] }));
    return rows.length === 0
      ? { status: 'PASS', count: 0, details: 'No bookings with expenses > 2x revenue' }
      : { status: 'WARN', count: rows.length,
          message: `${rows.length} bookings where expenses exceed 2x revenue — possible data error`,
          items: rows.map(r => ({ booking_id: r.booking_id, revenue: parseFloat(r.revenue).toFixed(2), expenses: parseFloat(r.expenses).toFixed(2) })) };
  });

  // ── 15. Deposit integrity (applied deposits match valid bookings via ledger) ─
  // booking_deposits uses booking_ledger_id (-> bookings_ledger) or booking_reference (text)
  await check('deposit_integrity', async () => {
    const { rows } = await pool.query(
      `SELECT bd.id, bd.booking_ledger_id, bd.booking_reference, bd.amount, bd.status
       FROM booking_deposits bd
       WHERE bd.status IN ('applied','confirmed')
         AND bd.booking_ledger_id IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM bookings_ledger bl WHERE bl.id = bd.booking_ledger_id)
       LIMIT 10`
    ).catch(() => ({ rows: [] }));
    return rows.length === 0
      ? { status: 'PASS', count: 0, details: 'All applied/confirmed deposits linked to valid ledger entries' }
      : { status: 'FAIL', count: rows.length,
          message: `${rows.length} applied deposits reference missing bookings_ledger records`,
          items: rows.map(r => ({ id: r.id, ledger_id: r.booking_ledger_id, ref: r.booking_reference, amount: r.amount })) };
  });

  // ── Persist audit run results ─────────────────────────────────────────────
  const totalIssues = issues.length;
  const totalWarnings = warnings.length;
  const overallStatus = totalIssues > 0 ? 'partial' : 'completed';

  await pool.query(
    `INSERT INTO accounting_system_audit_runs
       (run_id, started_by, scope, status, critical_issues, warnings, modules_tested, completed_at)
     VALUES ($1, 'regression_engine', 'full_regression', $2, $3::jsonb, $4::jsonb, $5::jsonb, NOW())
     ON CONFLICT (run_id) DO UPDATE
       SET status=$2, critical_issues=$3::jsonb, warnings=$4::jsonb,
           modules_tested=$5::jsonb, completed_at=NOW()`,
    [runId, overallStatus,
     JSON.stringify(issues),
     JSON.stringify(warnings),
     JSON.stringify(moduleResults)]
  ).catch(e => console.warn('Audit persist warn:', e.message));

  res.json({
    run_id:          runId,
    timestamp:       new Date().toISOString(),
    overall_status:  overallStatus,
    total_modules:   moduleResults.length,
    passed:          moduleResults.filter(m=>m.status==='PASS').length,
    warnings:        totalWarnings,
    failed:          totalIssues,
    modules:         moduleResults,
    issues,
    warnings: warnings,
  });
});

// ── FASE 9: GET /api/bookings/:id/integrity ───────────────────────────────
app.get('/api/bookings/:id/integrity', isAuthenticated, async (req, res) => {
  try {
    const result = await checkBookingIntegrity(req.params.id);
    if (!result) return res.status(404).json({ error: 'Booking no encontrado' });
    res.json(result);
  } catch (err) {
    console.error('Error integrity check:', err);
    res.status(500).json({ error: err.message });
  }
});

// ── GET /api/bookings/:id/ledger-summary ─────────────────────────────────
app.get('/api/bookings/:id/ledger-summary', isAuthenticated, async (req, res) => {
  try {
    const integrity = await checkBookingIntegrity(req.params.id);
    if (!integrity) return res.status(404).json({ error: 'Booking no encontrado' });

    // Get all transactions linked to this booking
    const { rows: txRows } = await pool.query(
      `SELECT t.*, ca.account_name, ca.account_code
       FROM transactions t
       JOIN chart_of_accounts ca ON t.account_id = ca.id
       WHERE t.booking_id = $1
       ORDER BY t.transaction_date ASC, t.created_at ASC`,
      [req.params.id]
    );

    // Get deposits
    const { rows: depRows } = await pool.query(
      `SELECT bd.*, b.name as boat_name
       FROM booking_deposits bd
       LEFT JOIN boats b ON bd.boat_id = b.id
       WHERE bd.booking_ledger_id IN (
         SELECT id FROM bookings_ledger WHERE notes LIKE 'booking:' || $1 || '%'
       )`,
      [req.params.id]
    );

    // Get expenses
    const { rows: expRows } = await pool.query(
      `SELECT * FROM boat_expenses WHERE booking_id = $1 AND (status IS NULL OR status NOT IN ('cancelled','voided','archived')) ORDER BY expense_date ASC`,
      [req.params.id]
    );

    res.json({ ...integrity, transactions: txRows, deposits: depRows, expenses: expRows });
  } catch (err) {
    console.error('Error ledger-summary:', err);
    res.status(500).json({ error: err.message });
  }
});

// ── FASE 10: GET /api/accounting/test-matej — verifica caso de prueba ─────
app.get('/api/accounting/test-matej', isAuthenticated, async (req, res) => {
  try {
    const bookingId = req.query.booking_id || 'book_matej_apr27_2026';

    // Find booking by ID or customer name 'Matej' on Apr 27
    const { rows: bkRows } = await pool.query(
      `SELECT * FROM bookings
       WHERE id = $1 OR (customer_name ILIKE '%Matej%' AND booking_date::text LIKE '2026-04-27%')
       ORDER BY created_at DESC LIMIT 1`,
      [bookingId]
    );
    if (!bkRows.length) {
      return res.json({
        found: false,
        message: 'Booking Matej Apr 27 no encontrado en el sistema',
        tip: 'Crea el booking primero con POST /api/bookings, luego ejecuta este test'
      });
    }
    const bk = bkRows[0];
    const integrity = await checkBookingIntegrity(bk.id);

    // Expected results for Matej $700 booking
    const expected = {
      total_revenue:    700.00,
      total_expenses:   561.00,  // fuel 300 + ice 6 + captain 144+111
      expected_profit:  139.00,
      deposit_bank:     250.00,
      cash_received:    450.00,
      captain_expected: 255.00,  // 144+111
      discrepancy_note: 'Captain overpayment: $5 (paid $255 vs expected $250)'
    };

    const assertions = [
      { check: 'expected_revenue == 700',     pass: Math.abs((integrity?.expected_revenue || 0) - 700) < 0.01 },
      { check: 'total_expenses ~= 561',       pass: Math.abs((integrity?.total_expenses || 0) - 561) < 1 },
      { check: 'expected_profit ~= 139',      pass: Math.abs((integrity?.expected_profit || 0) - 139) < 1 },
      { check: 'accounting_status != locked', pass: integrity?.accounting_status !== 'locked' },
    ];

    res.json({
      found: true,
      booking_id: bk.id,
      customer: bk.customer_name,
      booking_date: bk.booking_date,
      integrity,
      expected,
      assertions,
      all_passed: assertions.every(a => a.pass),
    });
  } catch (err) {
    console.error('Error test-matej:', err);
    res.status(500).json({ error: err.message });
  }
});

// ── POST /api/booking-payment — todos los tipos de pago del cliente ───────
app.post('/api/booking-payment', isAuthenticated, async (req, res) => {
  const pg = await pool.connect();
  try {
    await pg.query('BEGIN');
    const { nanoid } = await import('nanoid');
    const { booking_id, amount, date, notes, payment_type = 'cash' } = req.body;
    if (!booking_id || !amount || parseFloat(amount) <= 0) {
      return res.status(400).json({ error: 'booking_id y amount son requeridos' });
    }
    // R-1 fix: block legacy bookings
    const legacyErr = await assertBookingIsCurrentPeriod(booking_id, pg);
    if (legacyErr) { await pg.query('ROLLBACK'); return res.status(legacyErr.status).json(legacyErr); }
    const { rows: bkRows } = await pg.query(`SELECT * FROM bookings WHERE id = $1`, [booking_id]);
    if (!bkRows.length) { await pg.query('ROLLBACK'); return res.status(404).json({ error: 'Booking no encontrado' }); }
    const bk = bkRows[0];
    const payDate = date || new Date().toISOString().slice(0, 10);
    const amt = parseFloat(amount);

    // Resolve account and reference_type based on payment_type
    let accountId, refType, txDesc;
    if (payment_type === 'cash') {
      accountId = 'acc_cash_clearing_1015';
      refType   = 'cash_clearing';
      txDesc    = `Pago efectivo — ${bk.customer_name}${notes ? ' / ' + notes : ''}`;
    } else if (payment_type === 'zelle') {
      const { rows: bankRows } = await pg.query(`SELECT id FROM chart_of_accounts WHERE account_code='1010' LIMIT 1`);
      accountId = bankRows.length ? bankRows[0].id : 'acc_cash_clearing_1015';
      refType   = 'cash_clearing';
      txDesc    = `Pago Zelle — ${bk.customer_name}${notes ? ' / ' + notes : ''}`;
    } else if (payment_type === 'bank') {
      const { rows: bankRows } = await pg.query(`SELECT id FROM chart_of_accounts WHERE account_code='1010' LIMIT 1`);
      accountId = bankRows.length ? bankRows[0].id : 'acc_cash_clearing_1015';
      refType   = 'cash_clearing';
      txDesc    = `Pago bancario — ${bk.customer_name}${notes ? ' / ' + notes : ''}`;
    } else {
      // default fallback
      accountId = 'acc_cash_clearing_1015';
      refType   = 'cash_clearing';
      txDesc    = `Pago (${payment_type}) — ${bk.customer_name}${notes ? ' / ' + notes : ''}`;
    }

    const txId = 'tx_pay_' + nanoid(8);
    await pg.query(
      `INSERT INTO transactions
         (id, transaction_date, account_id, amount, transaction_type,
          description, reference_id, reference_type, boat_id, notes, booking_id)
       VALUES ($1, $2, $3, $4, 'income', $5, $6, $7, $8, $9, $10)`,
      [txId, payDate, accountId, amt, txDesc, booking_id,
       refType, bk.boat_id || null, notes || null, booking_id]
    );

    // Update booking balance
    const prevBalance = parseFloat(bk.balance_pending || bk.total_amount || 0);
    const newBalance  = Math.max(0, prevBalance - amt);
    const newPayStat  = newBalance <= 0.01 ? 'paid' : 'partial';
    const cashFlag    = ['cash', 'zelle'].includes(payment_type);
    await pg.query(
      `UPDATE bookings SET
         ${cashFlag ? 'has_cash_payment = true,' : ''}
         payment_status = $1, balance_pending = $2, updated_at = NOW()
       WHERE id = $3`,
      [newPayStat, newBalance, booking_id]
    );

    await pg.query('COMMIT');
    res.status(201).json({
      success: true, transaction_id: txId, payment_type,
      amount: amt, payment_status: newPayStat, balance_pending: newBalance
    });
  } catch (err) {
    await pg.query('ROLLBACK');
    console.error('Error booking-payment:', err);
    res.status(500).json({ error: err.message });
  } finally { pg.release(); }
});

// ── POST /api/bookings/:id/lock — cierre definitivo (accounting_status=locked)
app.post('/api/bookings/:id/lock', isAuthenticated, async (req, res) => {
  const pg = await pool.connect();
  try {
    await pg.query('BEGIN');
    const bookingId = req.params.id;

    // R-1 fix: block legacy bookings
    const legacyErr = await assertBookingIsCurrentPeriod(bookingId, pg);
    if (legacyErr) { await pg.query('ROLLBACK'); return res.status(legacyErr.status).json(legacyErr); }

    // Run full integrity check first
    const integrity = await checkBookingIntegrity(bookingId);
    if (!integrity) { await pg.query('ROLLBACK'); return res.status(404).json({ error: 'Booking no encontrado' }); }

    if (integrity.accounting_status === 'locked') {
      await pg.query('ROLLBACK');
      return res.status(400).json({ error: 'El booking ya está bloqueado' });
    }

    // Block cancelled bookings from being locked
    const { rows: bkStatusRows } = await pg.query(`SELECT status FROM bookings WHERE id = $1`, [bookingId]);
    if (bkStatusRows.length && ['cancelled','canceled','cancelado'].includes((bkStatusRows[0].status||'').toLowerCase())) {
      await pg.query('ROLLBACK');
      return res.status(409).json({ error: 'BOOKING_CANCELLED_ACCOUNTING_LOCKED', message: 'Booking cancelado — no se puede bloquear.' });
    }

    // Validation checks — hard blockers
    const errors = [];
    if (integrity.discrepancy_flag) errors.push('Hay discrepancia de pago pendiente');
    if (!integrity.revenue_recognized) errors.push('Revenue no ha sido reconocido');
    if (parseFloat(integrity.total_collected || 0) < parseFloat(integrity.expected_revenue || 0) - 0.01)
      errors.push('Pagos incompletos');
    if (parseFloat(integrity.total_ar_pending || 0) > 0.01)
      errors.push('Hay cuentas por cobrar pendientes');

    // General payables — ALLOW_CLOSE_WITH_OPEN_PAYABLES = true
    // Open payables are NOT hard blockers — they appear as warnings only
    const genPayBalance = parseFloat(integrity.general_payables_balance || 0);
    const openPayableWarnings = [];
    if (genPayBalance > 0.01) {
      const byType = integrity.general_payables_by_type || {};
      const pending = Object.entries(byType)
        .filter(([, v]) => v.balance_due > 0.01)
        .map(([t, v]) => `${t}: $${parseFloat(v.balance_due).toFixed(2)}`).join(', ');
      openPayableWarnings.push(`Cuentas por pagar pendientes (registradas en AP): ${pending}`);
    }

    const forceClose = req.body?.force === true;
    if (errors.length > 0 && !forceClose) {
      await pg.query('ROLLBACK');
      return res.status(400).json({
        error: 'No se puede cerrar: hay checks pendientes',
        errors, open_payable_warnings: openPayableWarnings,
        force_hint: 'Envía force:true para forzar el cierre'
      });
    }

    // Lock booking
    await pg.query(
      `UPDATE bookings SET status = CASE WHEN status != 'completed' THEN 'completed' ELSE status END,
       payment_status = 'paid', balance_pending = 0, updated_at = NOW() WHERE id = $1`,
      [bookingId]
    );
    await pg.query(
      `UPDATE bookings_ledger SET accounting_status = 'locked', status = 'completed'
       WHERE notes LIKE 'booking:' || $1 || '%'`,
      [bookingId]
    );

    // Audit trail transaction
    const { nanoid } = await import('nanoid');
    const lockTxId = 'tx_lock_' + nanoid(8);
    await pg.query(
      `INSERT INTO transactions
         (id, transaction_date, account_id, amount, transaction_type,
          description, reference_id, reference_type, notes, booking_id)
       VALUES ($1, CURRENT_DATE, 'acc_cash_clearing_1015', 0, 'income',
               $2, $3, 'manual_adjustment', $4, $5)`,
      [lockTxId,
       `CIERRE CONTABLE — Booking ${bookingId} bloqueado definitivamente`,
       bookingId,
       `Locked by: ${req.user?.id || 'system'} | Force: ${forceClose} | Warnings: ${errors.join('; ')||'ninguna'}`,
       bookingId]
    );

    await pg.query('COMMIT');
    const finalIntegrity = await checkBookingIntegrity(bookingId).catch(() => null);
    res.json({ success: true, accounting_status: 'locked', lock_tx_id: lockTxId,
               warnings: errors, open_payable_warnings: openPayableWarnings, integrity: finalIntegrity });
  } catch (err) {
    await pg.query('ROLLBACK');
    console.error('Error locking booking:', err);
    res.status(500).json({ error: err.message });
  } finally { pg.release(); }
});

// ── GET /api/audit/cancelled-bookings — forensic audit of cancelled bookings ──
app.get('/api/audit/cancelled-bookings', isAuthenticated, async (req, res) => {
  try {
    const { rows: cancelled } = await pool.query(`
      SELECT b.id, b.customer_name, b.booking_date, b.status, b.payment_status,
             b.accounting_status, b.total_amount, b.balance_pending, b.platform, b.boat_type
      FROM bookings b
      WHERE LOWER(b.status) IN ('cancelled','canceled','cancelado')
      ORDER BY b.booking_date DESC
    `);

    const results = [];
    for (const bk of cancelled) {
      const bookingId = bk.id;
      const [txRes, arRes, expRes] = await Promise.all([
        pool.query(
          `SELECT t.id, t.amount, t.reference_type, c.account_code
           FROM transactions t
           LEFT JOIN chart_of_accounts c ON c.id = t.account_id
           WHERE t.booking_id = $1`, [bookingId]
        ),
        pool.query(
          `SELECT id, amount, status FROM booking_receivables WHERE booking_id = $1`, [bookingId]
        ),
        pool.query(
          `SELECT id, amount, status FROM boat_expenses
           WHERE booking_id = $1 AND COALESCE(status,'') != 'cancelled'`, [bookingId]
        ),
      ]);

      const txs   = txRes.rows;
      const ars   = arRes.rows;
      const exps  = expRes.rows;

      const revenueTxs   = txs.filter(t => ['4010','4020','4030','4090'].includes(t.account_code));
      const cashClearing = txs.filter(t => t.reference_type === 'cash_clearing');
      const arPending    = ars.filter(a => ['pending','open'].includes((a.status||'')));

      const totalRevenue  = revenueTxs.reduce((s, t) => s + parseFloat(t.amount||0), 0);
      const totalAR       = arPending.reduce((s, a)  => s + parseFloat(a.amount||0), 0);
      const totalExp      = exps.reduce((s, e)       => s + parseFloat(e.amount||0), 0);
      const totalPayments = cashClearing.reduce((s, t) => s + parseFloat(t.amount||0), 0);
      const balance_pending = parseFloat(bk.balance_pending || 0);

      const issues = [];
      if (totalRevenue > 0)         issues.push(`Revenue activo: $${totalRevenue.toFixed(2)}`);
      if (totalAR > 0)              issues.push(`AR pendiente: $${totalAR.toFixed(2)}`);
      if (cashClearing.length > 0)  issues.push(`Cash clearing activo: ${cashClearing.length} tx(s)`);
      if (totalExp > 0)             issues.push(`Gastos activos: $${totalExp.toFixed(2)}`);
      if (balance_pending > 0)      issues.push(`balance_pending=$${balance_pending.toFixed(2)} debe ser 0`);

      results.push({
        booking_id:               bookingId,
        customer_name:            bk.customer_name,
        service_date:             bk.booking_date,
        platform:                 bk.platform,
        boat_type:                bk.boat_type,
        status:                   bk.status,
        payment_status:           bk.payment_status,
        accounting_status:        bk.accounting_status,
        total_amount:             parseFloat(bk.total_amount||0),
        balance_pending,
        total_payments,
        total_revenue_recognized: totalRevenue,
        total_receivable:         totalAR,
        total_expenses:           totalExp,
        transactions_count:       txs.length,
        cash_clearing_count:      cashClearing.length,
        has_revenue_transaction:  revenueTxs.length > 0,
        has_ar_balance:           totalAR > 0,
        has_cash_clearing:        cashClearing.length > 0,
        has_expenses:             exps.length > 0,
        issue_detected:           issues.length > 0,
        issues,
        recommended_fix: issues.length === 0 ? 'none'
          : balance_pending > 0    ? 'zero_balance_pending'
          : totalRevenue > 0       ? 'create_reversal_entry'
          : totalAR > 0            ? 'close_ar'
          : 'review_required',
      });
    }

    res.json({
      audit_date:                    new Date().toISOString(),
      total_cancelled:               results.length,
      critical_issues:               results.filter(r => r.issue_detected).length,
      bookings_affecting_revenue:    results.filter(r => r.has_revenue_transaction).length,
      bookings_with_ar:              results.filter(r => r.has_ar_balance).length,
      bookings_with_cash_clearing:   results.filter(r => r.has_cash_clearing).length,
      bookings_with_expenses:        results.filter(r => r.has_expenses).length,
      bookings_with_open_balance:    results.filter(r => r.balance_pending > 0).length,
      clean_bookings:                results.filter(r => !r.issue_detected).length,
      results,
    });
  } catch (err) {
    console.error('Error in cancelled bookings audit:', err);
    res.status(500).json({ error: err.message });
  }
});

